88	    /**
89	     * Dedicated audit logger. Successful owner creation emits a single line here carrying the new
90	     * owner's id, customer code, registration date and membership level, so audit side-effects can
91	     * be observed independently of the HTTP response.
92	     */
93	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
94	
95	    /**
96	     * Common street-type abbreviations expanded during address normalization. Keys and values are
97	     * upper-cased, matching the state of the address after whitespace and case normalization.
98	     */
99	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
100	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
101	
102	    /**
103	     * Required national-number length per E.164 country calling code. After normalization the leading
104	     * country code is stripped and the remaining national digits must match the expected count exactly
105	     * (e.g. {@code +61} requires 9 national digits, {@code +1} requires 10). Country codes not listed
106	     * here are only subject to the generic E.164 length bounds.
107	     */
108	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
109	        Map.of("1", 10, "61", 9);
110	
111	    /**
112	     * Fixed city-to-region table used to validate an owner's postcode. Cities not listed have no
113	     * known region and accept any well-formed (4-digit) postcode.
114	     */
115	    private static final Map<String, String> CITY_REGION =
116	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
117	
118	    /**
119	     * Inclusive 4-digit postcode range {@code [low, high]} allowed for each region: NSW 2000-2099,
120	     * VIC 3000-3099, QLD 4000-4099. A supplied postcode outside its city's region range is rejected.
121	     */
122	    private static final Map<String, int[]> REGION_POSTCODES =
123	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
124	
125	    /**
126	     * Request header carrying the caller-supplied idempotency key for owner creation. When a create
127	     * repeats with a key already seen, the originally created owner is returned instead of a duplicate.
128	     */
129	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
130	
131	    /**
132	     * Maps a previously seen idempotency key to the id of the owner created under it. Populated on each
133	     * successful create that carried an {@code Idempotency-Key}, and consulted on subsequent creates so a
134	     * repeat with the same key returns the original owner rather than creating a duplicate.
135	     */
136	    private final Map<String, Integer> idempotentOwnerIds = new ConcurrentHashMap<>();
