185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Override
187	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
188	        String idempotencyKey = idempotencyKey();
189	        if (idempotencyKey != null) {
190	            Integer existingId = idempotentOwnerIds.get(idempotencyKey);
191	            if (existingId != null) {
192	                Owner existing = this.clinicService.findOwnerById(existingId);
193	                if (existing != null) {
194	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
195	                }
196	            }
197	        }
198	        validateRequiredOwnerFields(ownerFieldsDto);
199	        HttpHeaders headers = new HttpHeaders();
200	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
201	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
202	        owner.setTelephone(normalizedTelephone);
203	        owner.setEmail(normalizeEmail(owner.getEmail()));
204	        applyAddress(owner);
205	        validatePostcode(owner.getPostcode(), owner.getCity());
206	        rejectFutureRegistrationDate(owner.getRegistrationDate());
207	        LocalDate effectiveRegistrationDate =
208	            owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
209	        owner.setRegistrationDate(rollToBusinessDay(effectiveRegistrationDate));
210	        rejectDailyLimitReached(owner.getRegistrationDate());
211	        rejectCityAtCapacity(owner.getCity());
212	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
213	        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
214	        rejectDuplicateIdentity(owner, sharesHousehold);
215	        assignPossibleDuplicate(owner, normalizedTelephone, sharesHousehold);
216	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
217	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
218	        owner.setHouseholdSize(countHousehold(owner.getHouseholdId()));
219	        owner.setCustomerCode(buildCustomerCode(owner, normalizedTelephone));
220	        this.clinicService.saveOwner(owner);
221	        if (idempotencyKey != null) {
222	            idempotentOwnerIds.put(idempotencyKey, owner.getId());
223	        }
224	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
225	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
226	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
227	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
228	        headers.setLocation(UriComponentsBuilder.newInstance()
229	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
230	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
231	    }
