17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
27	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
28	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
29	    @Mapping(target = "locality", expression = "java(locality(owner))")
30	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
31	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
32	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
33	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
34	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
35	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
36	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
37	    OwnerDto toOwnerDto(Owner owner);
38	
39	    /**
40	     * Builds the owner's self link, formatted {@code '/api/owners/<id>'} where {@code id} is the
41	     * owner's id. Returns {@code null} when the owner has no id.
42	     */
43	    default String selfLink(Owner owner) {
44	        Integer id = owner.getId();
45	        if (id == null) {
46	            return null;
47	        }
48	        return "/api/owners/" + id;
49	    }
50	
51	    /**
52	     * Derives the owner's age band from the birth date, computed as the owner's age on the
53	     * registration date: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
54	     * {@code SENIOR} at 65 or older. Returns {@code null} when the birth date or registration
55	     * date is absent, so an owner created without a birth date carries no age band.
56	     */
57	    default org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum ageBand(Owner owner) {
58	        java.time.LocalDate birthDate = owner.getBirthDate();
59	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
60	        if (birthDate == null || registrationDate == null) {
61	            return null;
62	        }
63	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
64	        if (age < 18) {
65	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.MINOR;
66	        }
67	        if (age < 65) {
68	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.ADULT;
69	        }
70	        return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.SENIOR;
71	    }
72	
73	    /**
74	     * Computes the owner's check digit: a single Luhn check digit (0-9) over the digits contained
75	     * in the owner's customer code. Returns {@code null} when the customer code is absent.
76	     */
77	    default Integer checkDigit(Owner owner) {
78	        String customerCode = owner.getCustomerCode();
79	        if (customerCode == null) {
80	            return null;
81	        }
82	        int sum = 0;
83	        boolean dbl = true;
84	        for (int i = customerCode.length() - 1; i >= 0; i--) {
85	            char c = customerCode.charAt(i);
86	            if (c < '0' || c > '9') {
87	                continue;
88	            }
89	            int d = c - '0';
90	            if (dbl) {
91	                d *= 2;
92	                if (d > 9) {
93	                    d -= 9;
94	                }
95	            }
96	            sum += d;
97	            dbl = !dbl;
98	        }
99	        return (10 - (sum % 10)) % 10;
100	    }
101	
102	    /**
103	     * Derives the owner's duplicate-detection identity key, formatted
104	     * {@code '<normalizedTelephone>|<email>|<householdId>'}. The email and household-id segments are
105	     * empty when the respective field is absent. The telephone and email are already stored in their
106	     * normalized (E.164 / lower-cased) form, so the stored values are used directly. This is the single
107	     * key against which owner duplicates are detected: two owners collide only when their whole keys
108	     * match.
109	     */
110	    default String identityKey(Owner owner) {
111	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
112	        String email = owner.getEmail() == null ? "" : owner.getEmail();
113	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
114	        return telephone + "|" + email + "|" + householdId;
115	    }
116	
117	    /**
118	     * Fixed city-to-region table used to derive an owner's locality.
119	     */
120	    java.util.Map<String, String> CITY_REGION =
121	        java.util.Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
122	
123	    /**
124	     * Inclusive 4-digit postcode range {@code [low, high]} owned by each region: NSW 2000-2099,
125	     * VIC 3000-3099, QLD 4000-4099. Used to resolve an owner's region from the postcode first.
126	     */
127	    java.util.Map<String, int[]> REGION_POSTCODES =
128	        java.util.Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
129	
130	    /**
131	     * Derives the owner's locality, the {@code REGION} segment of the owner's customer code (the
132	     * region-and-hash identity {@code '<REGION>-<HASH8>'}). Only when no customer code is present does
133	     * it fall back to deriving the region directly, preferring the postcode's {@link #REGION_POSTCODES}
134	     * range and then the fixed {@link #CITY_REGION} city table. Returns the canonical region string, or
135	     * {@code "UNKNOWN"} when neither source resolves a region.
136	     */
137	    default String locality(Owner owner) {
138	        String customerCode = owner.getCustomerCode();
139	        if (customerCode != null) {
140	            int dash = customerCode.indexOf('-');
141	            String region = dash >= 0 ? customerCode.substring(0, dash) : customerCode;
142	            if (!region.isEmpty()) {
143	                return region;
144	            }
145	        }
146	        String postcode = owner.getPostcode();
147	        if (postcode != null) {
148	            try {
149	                int value = Integer.parseInt(postcode.trim());
150	                for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
151	                    int[] range = entry.getValue();
152	                    if (value >= range[0] && value <= range[1]) {
153	                        return entry.getKey();
154	                    }
155	                }
156	            }
157	            catch (NumberFormatException ex) {
158	                // Not a numeric postcode; fall back to the city table below.
159	            }
160	        }
161	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
162	    }
163	
164	    /**
165	     * Fixed region-to-timezone table used to derive an owner's timezone as an IANA name.
166	     */
167	    java.util.Map<String, String> REGION_TIMEZONE =
168	        java.util.Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
169	
170	    /**
171	     * Derives the owner's timezone as an IANA name from the owner's {@link #locality(Owner) locality}
172	     * (region) via the fixed {@link #REGION_TIMEZONE} table: {@code NSW -> Australia/Sydney},
173	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}. Returns {@code null} when
174	     * the region does not resolve to a known timezone (e.g. the locality is {@code "UNKNOWN"}).
175	     */
176	    default String timezone(Owner owner) {
177	        return REGION_TIMEZONE.get(locality(owner));
178	    }
179	
180	    /**
181	     * Known E.164 country calling codes, longest first, used to split a stored E.164 telephone into
182	     * its country code and national digits when formatting {@link #telephoneDisplay(Owner)}.
183	     */
184	    String[] TELEPHONE_COUNTRY_CODES = {"61", "1"};
185	
186	    /**
187	     * Formats the owner's stored E.164 telephone for humans: the country code, a space, then the
188	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
189	     * The country code is recognised from the {@link #TELEPHONE_COUNTRY_CODES} table; when none matches,
190	     * all digits after the {@code '+'} are treated as the national number. Returns {@code null} when the
191	     * telephone is absent, and the value unchanged when it is not a {@code '+'}-prefixed E.164 number.
192	     */
193	    default String telephoneDisplay(Owner owner) {
194	        String telephone = owner.getTelephone();
195	        if (telephone == null) {
196	            return null;
197	        }
198	        if (!telephone.startsWith("+")) {
199	            return telephone;
200	        }
201	        String digits = telephone.substring(1);
202	        if (!digits.chars().allMatch(Character::isDigit)) {
203	            return telephone;
204	        }
205	        String countryCode = "";
206	        for (String code : TELEPHONE_COUNTRY_CODES) {
207	            if (digits.startsWith(code) && digits.length() > code.length()) {
208	                countryCode = code;
209	                break;
210	            }
211	        }
212	        String national = digits.substring(countryCode.length());
213	        StringBuilder grouped = new StringBuilder();
214	        for (int i = 0; i < national.length(); i++) {
215	            if (i > 0 && i % 3 == 0) {
216	                grouped.append(' ');
217	            }
218	            grouped.append(national.charAt(i));
219	        }
220	        return "+" + countryCode + " " + grouped;
221	    }
222	
223	    /**
224	     * Derives the owner's preferred contact channel: {@code "EMAIL"} when an email address is
225	     * present (non-blank), otherwise {@code "PHONE"}.
226	     */
227	    default String contactPreference(Owner owner) {
228	        String email = owner.getEmail();
229	        return email != null && !email.isBlank() ? "EMAIL" : "PHONE";
230	    }
231	
232	    /**
233	     * Computes the owner's membership points. Starts at {@code 0} and adds {@code 2} when an email
234	     * is present, {@code 1} when the owner has no namesakes ({@code namesakeCount} is {@code 0}),
235	     * {@code 2} for a household of {@code 3} or more ({@code householdSize}), and {@code 3} when the
236	     * owner's tenure spans at least one elapsed fiscal year (the {@code registrationDate}'s fiscal
237	     * year is earlier than the current date's fiscal year).
238	     */
239	    default Integer membershipPoints(Owner owner) {
240	        Integer namesakeCount = owner.getNamesakeCount();
241	        String email = owner.getEmail();
242	        Integer householdSize = owner.getHouseholdSize();
243	        int points = 0;
244	        if (email != null && !email.isBlank()) {
245	            points += 2;
246	        }
247	        if (namesakeCount != null && namesakeCount == 0) {
248	            points += 1;
249	        }
250	        if (householdSize != null && householdSize >= 3) {
251	            points += 2;
252	        }
253	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
254	        boolean hasTenure = registrationDate != null
255	            && fiscalYearValue(java.time.LocalDate.now()) - fiscalYearValue(registrationDate) >= 1;
256	        if (hasTenure) {
257	            points += 3;
258	        }
259	        return points;
260	    }
261	
262	    /**
263	     * Derives the owner's membership level, a number from 1 to 4, from the owner's
264	     * {@link #membershipPoints(Owner) membership points}: level {@code 1} for {@code 0-1} points,
265	     * {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more.
266	     */
267	    default Integer membershipLevel(Owner owner) {
268	        int points = membershipPoints(owner);
269	        if (points <= 1) {
270	            return 1;
271	        }
272	        if (points <= 3) {
